(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const fmt=n=>Math.floor(n).toLocaleString('en-US');
  const KEY='rank-up-awakening-save-v1';
  const fresh=()=>({level:7,xp:2160,xpNext:3000,gold:1240,aether:25,hp:840,maxHp:840,attack:78,defense:24,rank:'F',points:0,kills:0,wave:2,waveKills:2,runGold:280,runXp:460,inventory:[{name:'Gloamsteel Edge',slot:'Weapon',rarity:'Rare',icon:'⚔',attack:18,upgrade:0,locked:false},{name:'Warden’s Mantle',slot:'Chest Armor',rarity:'Uncommon',icon:'♢',defense:9,upgrade:0,locked:false}],equipped:0,companions:[{name:'Vesper',type:'SHADOW WOLF',level:4,icon:'狼',active:true},{name:'Hollow Wisp',type:'ARCANE COMPANION',level:3,icon:'✧',active:true},{name:'Mossback',type:'ANCIENT GOLEM',level:2,icon:'◉',active:true}],attributes:{Strength:12,Agility:9,Vitality:11,Intelligence:7},claimed:{},last:Date.now(),sound:false,auto:true});
  let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};state.attributes={...fresh().attributes,...(state.attributes||{})};state.inventory=Array.isArray(state.inventory)?state.inventory:fresh().inventory;state.companions=Array.isArray(state.companions)?state.companions:fresh().companions}catch{state=fresh()}
  const enemyTypes=[{name:'Catacomb Guard',type:'SKELETON',hp:180,xp:82,gold:44,color:'#b9c1bd'},{name:'Gravebound Acolyte',type:'UNDEAD',hp:235,xp:105,gold:57,color:'#9bb9a9'},{name:'Hollow Stalker',type:'DARK CREATURE',hp:275,xp:126,gold:66,color:'#977bd4'}];
  let enemy={...enemyTypes[0],maxHp:180},enemyHp=140,attackClock=0,lastFrame=performance.now(),playerX=.49,playerY=.76,targetX=.7,hitFlash=0,shake=0,particles=[],floating=[],cooldowns={strike:0,burst:0,heal:0,ultimate:0},modalLock=false,sceneW=800,sceneH=600;
  const canvas=$('#gameCanvas'),ctx=canvas.getContext('2d');
  function save(){state.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('Save unavailable',e)}}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
  function updateHud(){const xpPct=state.xp/state.xpNext*100,hpPct=state.hp/state.maxHp*100;$('#gold').textContent=fmt(state.gold);$('#aether').textContent=fmt(state.aether);$('#side-level').textContent=state.level;$('.level-orb').textContent=state.level;$('#healthText').textContent=`${fmt(state.hp)} / ${fmt(state.maxHp)}`;$('#playerHealth').style.width=`${hpPct}%`;$('#xpText').textContent=`${fmt(state.xp)} / ${fmt(state.xpNext)} XP`;$('#xpBar').style.width=`${xpPct}%`;$('#waveNum').textContent=String(state.wave).padStart(2,'0');$('#side-wave').textContent=String(state.wave).padStart(2,'0');$('#waveEnemies').textContent=String(Math.max(1,5-state.waveKills));$('#waveBar').style.width=`${Math.min(100,(state.waveKills/5)*100)}%`;$('#enemyName').textContent=enemy.name;$('#enemyLevel').textContent=`LV. ${String(Math.min(25,4+state.wave)).padStart(2,'0')}`;$('#enemyType').textContent=enemy.type;$('#enemyHealth').style.width=`${clamp(enemyHp/enemy.maxHp*100,0,100)}%`;$('#enemyHpText').textContent=`${fmt(Math.max(0,enemyHp))} / ${fmt(enemy.maxHp)}`;$('#runGold').textContent=`+${fmt(state.runGold)}`;$('#runXp').textContent=`+${fmt(state.runXp)}`;$('#runLoot').textContent=String(state.inventory.length-1);$('#power').textContent=fmt(state.attack*10+state.defense*4+state.level*12);$('#objectiveBar').style.width=`${Math.min(100,(state.wave-1)*10+state.waveKills*2)}%`;$('#objectiveText').textContent=`${Math.min(10,state.wave-1)} / 10`;$('.auto-toggle').classList.toggle('off',!state.auto);$('.auto-toggle b').textContent=state.auto?'ON':'OFF';$('#attackTimer').textContent=`${Math.max(0,2.1-attackClock).toFixed(1)}s`}
  function gainXp(amount){state.xp+=amount;state.runXp+=amount;while(state.xp>=state.xpNext){state.xp-=state.xpNext;state.level++;state.points+=3;state.maxHp+=38;state.hp=Math.min(state.maxHp,state.hp+90);state.attack+=4;state.xpNext=Math.round(state.xpNext*1.22);toast(`LEVEL UP · LEVEL ${state.level}`);feed(`Hunter reached level ${state.level}`)}updateHud()}
  function addFeed(text){const f=$('#combatFeed');const d=document.createElement('div');d.innerHTML='<i></i> '+text;f.prepend(d);while(f.children.length>3)f.lastElementChild.remove()}
  function dropLoot(boss=false){const rarities=['Common','Uncommon','Rare','Epic'];const rarity=boss?'Epic':(['Common','Common','Uncommon','Rare'][Math.floor(Math.random()*4)]);const names=['Ashen Sabatons','Gravetide Ring','Warden’s Grips','Boneglass Charm','Duskfall Circlet'];const slots=['Boots','Ring','Gloves','Artifact','Helmet'];const item={name:names[Math.floor(Math.random()*names.length)],slot:slots[Math.floor(Math.random()*slots.length)],rarity,icon:['♧','◇','♢','✧','⌑'][Math.floor(Math.random()*5)],attack:Math.floor(4+Math.random()*12)+(boss?12:0),defense:Math.floor(2+Math.random()*8)+(boss?7:0),upgrade:0,locked:false};state.inventory.push(item);state.runGold+=0;$('#runLoot').textContent=String(state.inventory.length-1);$('#lootToast').innerHTML='✦ <span>'+rarity+' · '+item.name+'</span>';$('#lootToast').classList.add('show');setTimeout(()=>$('#lootToast').classList.remove('show'),2400);addFeed(`${rarity} equipment recovered`);save()}
  function killEnemy(){state.kills++;state.waveKills++;const boss=state.wave>=10;if(boss){state.gold+=450;state.runGold+=450;state.aether+=15;gainXp(enemy.xp*4);dropLoot(true);addFeed('Skeleton King defeated · 15 Aether acquired');toast('GATE CLEARED · +15 AETHER');$('#sceneSkip').classList.add('show');$('#skipWave').classList.add('show');state.wave=1;state.waveKills=0;$('#bossAlert').classList.remove('show')}else{const gold=enemy.gold+Math.floor(Math.random()*13);state.gold+=gold;state.runGold+=gold;gainXp(enemy.xp);if(Math.random()<.14)dropLoot();if(state.waveKills>=5){state.wave++;state.waveKills=0;addFeed(`Wave ${state.wave} · new threats incoming`);if(state.wave===10){enemy={name:'THE SKELETON KING',type:'GATE GUARDIAN',hp:1850,maxHp:1850,xp:300,gold:250,color:'#d9bd7d'};enemyHp=enemy.hp;$('#bossAlert').classList.add('show');setTimeout(()=>$('#bossAlert').classList.remove('show'),2500)}else spawnEnemy()}}if(!boss)spawnEnemy();updateHud();save()}
  function spawnEnemy(){if(state.wave>=10&&enemy.name==='THE SKELETON KING'&&enemyHp>0)return;enemy={...enemyTypes[Math.floor(Math.random()*enemyTypes.length)]};enemy.maxHp=Math.round(enemy.hp*(1+Math.max(0,state.wave-1)*.19));enemyHp=enemy.maxHp;targetX=.66+Math.random()*.15;updateHud()}
