function view(name){const battle=$('#battleView'),content=$('#contentView');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='battle'){battle.classList.remove('hidden');content.classList.add('hidden');return}battle.classList.add('hidden');content.classList.remove('hidden');renderView(name)}
function header(kicker,title,desc){return `<div class="view-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><button class="back-battle" data-view="battle">◈ &nbsp; RETURN TO BATTLE</button></div>`}
function renderView(name){const el=$('#contentView');const views={character:renderCharacter,equipment:renderEquipment,skills:renderSkills,companions:renderCompanions,dungeons:renderDungeons,quests:renderQuests,shop:renderShop};(views[name]||renderCharacter)(el);$$('[data-view]',el).forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));}
function renderCharacter(el){el.innerHTML=header('HUNTER DOSSIER · RANK F', 'CHARACTER', 'A hunter shaped by each descent into the Gate.')+`<div class="content-grid"><div class="info-card"><h3>FIELD ATTRIBUTES <span class="tag">${state.points} POINTS AVAILABLE</span></h3><div class="stat-grid">${Object.entries(state.attributes).map(([k,v])=>`<div class="stat-box"><small>${k.toUpperCase()}</small><b>${v} ${state.points?`<button data-attr="${k}" aria-label="Increase ${k}">+</button>`:''}</b></div>`).join('')}</div></div><div class="info-card"><h3>COMBAT PROFILE</h3><div class="stat-grid"><div class="stat-box"><small>MAX HEALTH</small><b>${fmt(state.maxHp)}</b></div><div class="stat-box"><small>ATTACK</small><b>${fmt(state.attack)}</b></div><div class="stat-box"><small>DEFENSE</small><b>${fmt(state.defense)}</b></div><div class="stat-box"><small>CRITICAL CHANCE</small><b>14%</b></div></div></div><div class="info-card wide"><h3>HUNTER PROGRESSION</h3><p>Rank F · Novice Hunter. The Hunter examination becomes available at level 10. Your class awakening is still dormant; complete Gate challenges to reveal the power within.</p><div class="meter"><span style="width:${Math.min(100,state.xp/state.xpNext*100)}%"></span></div><p style="margin-top:7px">Level ${state.level} · ${fmt(state.xp)} / ${fmt(state.xpNext)} XP · ${state.kills} monsters defeated</p></div></div>`;$$('[data-attr]',el).forEach(b=>b.onclick=()=>{if(state.points<=0)return;state.points--;state.attributes[b.dataset.attr]++;if(b.dataset.attr==='Vitality'){state.maxHp+=12;state.hp+=12}if(b.dataset.attr==='Strength')state.attack+=2;save();renderCharacter(el);toast(`${b.dataset.attr} increased`);updateHud()})}
function renderEquipment(el){const items=state.inventory;el.innerHTML=header('HUNTER LOADOUT · GEAR', 'EQUIPMENT', `${items.length} items recovered · equipped bonuses contribute to combat power.`)+`<div class="content-grid"><div class="info-card wide"><h3>INVENTORY <span class="tag">${items.length} / 40 SLOTS</span></h3><div class="inventory-list">${items.map((it,i)=>`<div class="item-row"><div class="item-icon ${it.rarity==='Epic'?'gold':''}">${it.icon}</div><div class="item-copy"><b>${it.name} ${it.upgrade?`+${it.upgrade}`:''}</b><small>${it.rarity} · ${it.slot} · +${it.attack||0} ATK · +${it.defense||0} DEF</small></div>${state.equipped===i?'<span class="tag">EQUIPPED</span>':`<button data-equip="${i}">EQUIP</button>`}<button data-sell="${i}" ${it.locked?'disabled':''}>SELL</button></div>`).join('')}</div></div><div class="info-card"><h3>FIELD FORGE</h3><p>Upgrade your equipped weapon using gold. Upgrades are guaranteed in this prototype and never destroy equipment.</p><div class="stat-box" style="margin-top:12px"><small>GLOAMSTEEL EDGE · UPGRADE +${items[0]?.upgrade||0}</small><b>Cost: ${300+(items[0]?.upgrade||0)*250} gold</b></div><button class="action-button" id="upgradeItem">UPGRADE WEAPON</button></div><div class="info-card"><h3>RECENT DROP</h3><p>${items.length>2?`${items.at(-1).rarity} ${items.at(-1).name} · ${items.at(-1).slot}`:'No new drops yet. Defeat enemies for a chance at equipment.'}</p></div></div>`;$$('[data-equip]',el).forEach(b=>b.onclick=()=>{state.equipped=Number(b.dataset.equip);state.attack=78+(items[state.equipped]?.attack||0);save();renderEquipment(el);updateHud();toast('Equipment changed')});$$('[data-sell]',el).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.sell);if(state.equipped===i||items[i].locked)return;const sold=items.splice(i,1)[0];if(state.equipped>i)state.equipped--;state.gold+=90;save();renderEquipment(el);updateHud();toast(`${sold.name} sold for 90 gold`)});$('#upgradeItem',el).onclick=()=>{const weapon=items[0];const cost=300+(weapon.upgrade||0)*250;if(state.gold<cost){toast('Not enough gold');return}state.gold-=cost;weapon.upgrade=(weapon.upgrade||0)+1;weapon.attack=(weapon.attack||0)+3;save();renderEquipment(el);updateHud();toast(`Weapon upgraded to +${weapon.upgrade}`)}}
function renderSkills(el){el.innerHTML=header('COMBAT ARTS · MANUAL ACTIVATION','SKILLS','Activate skills in combat with the Q, W, E and R keys or touchscreen buttons.')+`<div class="content-grid">${[['Rending Strike','Q · 7 sec cooldown','A focused melee blow that deals 2.2× attack damage.','⚔'],['Umbral Nova','W · 12 sec cooldown','Two pulses of dark energy strike the target.','✷'],['Second Breath','E · 18 sec cooldown','Restore up to 38% of maximum health.','✚'],['Nightfall','R · 35 sec cooldown','Unleash the ultimate; deals 4.5× attack damage.','✧']].map(([n,c,d,i])=>`<div class="info-card"><div class="item-row"><div class="item-icon">${i}</div><div class="item-copy"><b>${n}</b><small>${c}</small></div><span class="tag">LV. 1</span></div><p style="margin-top:12px">${d}</p><div class="meter"><span style="width:25%"></span></div></div>`).join('')}<div class="info-card wide"><h3>PASSIVE · HUNTER'S INSTINCT</h3><p>Automatic combat remains active while you manage character systems. Your hunter approaches targets, attacks, and claims basic rewards without movement input.</p></div></div>`}
