  function renderQuests(el){const tasks=[['Clear 5 enemies','Defeat any 5 dungeon enemies',state.kills>=5,'quest-kills'],['Explore the Catacombs','Complete a dungeon wave',state.wave>2,'quest-wave'],['Hunter’s first steps','Reach character level 8',state.level>=8,'quest-level']];el.innerHTML=header('DAILY CONTRACTS · RESET 00:00 UTC','QUESTS','Complete field objectives for one-time prototype rewards.')+`<div class="content-grid"><div class="info-card wide"><h3>DAILY CONTRACTS</h3><div class="quest-list">${tasks.map(([title,desc,done,id],i)=>`<div class="quest-line"><div class="quest-check">${done?'✓':'○'}</div><div><b>${title}</b><small>${desc} · Reward: ${i===0?90:i===1?120:150} gold</small></div><button data-quest="${id}" ${!done||state.claimed[id]?'disabled':''}>${state.claimed[id]?'CLAIMED':done?'CLAIM':'IN PROGRESS'}</button></div>`).join('')}</div></div><div class="info-card"><h3>REWARD POLICY</h3><p>Quest claims are saved locally and cannot be claimed twice on this device. Premium currency is not awarded for ad views or real-money simulation.</p></div><div class="info-card"><h3>ACHIEVEMENT · GATE WALKER</h3><p>${state.kills} / 50 enemies defeated. This milestone is tracked in your local save.</p><div class="meter"><span style="width:${Math.min(100,state.kills/50*100)}%"></span></div></div></div>`;$$('[data-quest]',el).forEach(b=>b.onclick=()=>{const id=b.dataset.quest;if(state.claimed[id])return;state.claimed[id]=true;state.gold+=id==='quest-kills'?90:id==='quest-wave'?120:150;save();renderQuests(el);updateHud();toast('Quest reward claimed')})}
  function renderShop(el){const packs=[['100','Aether Shards','Starter bundle'],['550','Aether Crystal','Hunter bundle'],['1,200','Aether Crystal','Gatebreaker bundle'],['2,600','Aether Crystal','Awakening bundle'],['7,000','Aether Core','Sovereign bundle'],['15,000','Aether Core','Legacy bundle']];el.innerHTML=header('AETHER EXCHANGE · DEVELOPMENT','AETHER SHOP','Premium products are display-only. Real Google Play Billing is not connected.')+`<div class="content-grid"><div class="info-card wide"><h3>CRYSTAL RESERVE · ${fmt(state.aether)} AETHER</h3><div class="shop-grid">${packs.map(([amount,type,desc])=>`<div class="shop-tile"><div class="crystal-large">✧</div><b>${amount} AETHER</b><small>${type} · ${desc}</small><button data-pack>PRODUCT INFO</button></div>`).join('')}<div class="shop-note">This prototype has no real-money checkout and does not award purchased currency. Proposed prices are intentionally omitted because actual localized pricing requires Google Play Billing.</div></div></div><div class="info-card"><h3>NO PURCHASES AVAILABLE</h3><p>Transactions, subscriptions, VIP benefits, and paid products must be integrated and verified through Google Play Billing and a secure backend before release.</p></div><div class="info-card"><h3>FREE GAMEPLAY REWARDS</h3><p>Earn gold, equipment, and progression through the Forgotten Catacombs. The first Skeleton King clear awards 15 Aether.</p></div></div>`;$$('[data-pack]',el).forEach(b=>b.onclick=()=>toast('Store products are not connected in this prototype'))}
