+    for(const f of floating){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.font='700 18px "Barlow Condensed",sans-serif';ctx.textAlign='center';ctx.shadowColor=f.color;ctx.shadowBlur=8;ctx.fillText(f.text,f.x,f.y-(1-f.life)*46);ctx.shadowBlur=0}ctx.globalAlpha=1;
+    const vignette=ctx.createRadialGradient(w*.5,h*.48,h*.2,w*.5,h*.5,h*.74);vignette.addColorStop(.5,'rgba(3,5,8,0)');vignette.addColorStop(1,'rgba(3,5,8,.52)');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);
+  }
+  function resizeCanvas(){const r=$('#scene').getBoundingClientRect();sceneW=Math.max(1,r.width);sceneH=Math.max(1,r.height);const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(sceneW*dpr);canvas.height=Math.round(sceneH*dpr)}
+  function playTone(freq,duration){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}}
+  function bindEvents(){
+    $$('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
+    $$('[data-skill]').forEach(b=>b.addEventListener('click',()=>useSkill(b.dataset.skill)));
+    $('#autoBtn').addEventListener('click',()=>{state.auto=!state.auto;updateHud();save();toast(state.auto?'Auto-hunt resumed':'Auto-hunt paused')});
+    $('#soundBtn').addEventListener('click',()=>{state.sound=!state.sound;$('#soundBtn').classList.toggle('on',state.sound);save();if(state.sound)playTone(540,.08);toast(`Sound ${state.sound?'on':'off'}`)});
+    $('#fullscreenBtn').addEventListener('click',()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.()});
+    $('#skipWave').addEventListener('click',()=>{openModal(`<div class="eyebrow">GATE 01 · THE SUNKEN CATHEDRAL</div><h2>EXPEDITION CONTINUES</h2><p>The Skeleton King has fallen. Your rewards are already secured; descend again whenever you are ready.</p><div class="modal-stats"><div><small>GOLD THIS RUN</small><b>+${fmt(state.runGold)}</b></div><div><small>EXPERIENCE</small><b>+${fmt(state.runXp)} XP</b></div><div><small>EQUIPMENT</small><b>${state.runLoot} found</b></div><div><small>GATE STATUS</small><b>GUARDIAN CLEARED</b></div></div><button class="action-button" id="continueGate">CONTINUE HUNTING</button>`);$('#continueGate').onclick=closeModal;$('#skipWave').classList.remove('show')});
+    $('#scene').addEventListener('pointerdown',e=>{if(e.target===canvas&&state.auto===false)playerHit(1,'MANUAL ATTACK')});
+    document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if(e.repeat||modalLock)return;const key=e.key.toLowerCase(),map={q:'strike',w:'burst',e:'heal',r:'ultimate'};if(map[key]){e.preventDefault();useSkill(map[key])}});
+    window.addEventListener('resize',resizeCanvas);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('pagehide',save);
+  }
+  function tick(now){const dt=Math.min(.05,Math.max(0,(now-lastFrame)/1000));lastFrame=now;const t=now/1000;attackClock+=dt;
+    Object.keys(cooldowns).forEach(k=>{cooldowns[k]=Math.max(0,cooldowns[k]-dt);const b=$(`[data-skill="${k}"]`);if(b){b.classList.toggle('cooling',cooldowns[k]>0);const overlay=$('.cooldown',b);if(overlay)overlay.style.height=`${cooldowns[k]/({strike:7,burst:12,heal:18,ultimate:35}[k])*100}%`;b.title=cooldowns[k]>0?`${Math.ceil(cooldowns[k])} seconds`:'Ready'}});
+    if(state.auto&&!modalLock&&attackClock>=2.1){attackClock=0;playerHit(1,'STRIKE');state.companions.filter(c=>c.active).forEach((c,i)=>{if(enemyHp>0){const d=Math.round((state.attack*.13+i*2)*(1+c.level*.04));enemyHp-=d;floating.push({x:sceneW*(targetX+.035),y:sceneH*(.43+i*.035),text:`${d}`,life:.8,color:['#9ad6c9','#ad93ee','#dfc17b'][i]});burstParticles(sceneW*targetX,sceneH*.58,['#8bdac8','#aa92eb','#d8be7b'][i],3);if(enemyHp<=0)killEnemy()}});updateHud()}
+    if(!modalLock){attackClock+=0;tick.enemyAttack=(tick.enemyAttack||0)+dt;if(tick.enemyAttack>3.1){tick.enemyAttack=0;const guard=Math.min(3,state.companions.filter(c=>c.active).length);const damage=Math.max(3,Math.round((enemy.name==='THE SKELETON KING'?33:15+state.wave*1.5)-guard*3-state.defense*.18));state.hp-=damage;hitFlash=.16;floating.push({x:sceneW*.43,y:sceneH*.42,text:`-${damage}`,life:.8,color:'#ef8d85'});if(state.hp<=0){state.hp=Math.round(state.maxHp*.5);toast('Hunter recovered at the Gate · 50% health restored');addFeed('Hunter returned to the expedition')}updateHud();save()}}
+    particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy+=25*dt;return p.life>0});floating=floating.filter(f=>{f.life-=dt;f.y-=dt*12;return f.life>0});hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt*18);
+    $('#attackTimer').textContent=`${Math.max(0,2.1-(attackClock%2.1)).toFixed(1)}s`;drawScene(t);requestAnimationFrame(tick)
+  }
+  function init(){
+    if(!enemyHp||!Number.isFinite(enemyHp))enemyHp=enemy.maxHp;
+    const active=state.companions.find(c=>c.active);if(active)active.name=active.name||'Vesper';
+    bindEvents();resizeCanvas();spawnEnemy();updateHud();view('battle');
+    if(state.sound)$('#soundBtn').classList.add('on');
+    requestAnimationFrame(tick);handleOffline();
+    setInterval(save,15000);
+  }
+  init();
 })();

