(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const fmt=n=>Math.floor(n).toLocaleString('en-US');
  const KEY='rank-up-awakening-save-v1';
  const fresh=()=>({level:7,xp:2160,xpNext:3000,gold:1240,aether:25,hp:840,maxHp:840,attack:78,defense:24,rank:'F',points:0,kills:0,wave:2,waveKills:2,runGold:280,runXp:460,runLoot:0,inventory:[{name:'Gloamsteel Edge',slot:'Weapon',rarity:'Rare',icon:'⚔',attack:18,upgrade:0,locked:false},{name:'Warden’s Mantle',slot:'Chest Armor',rarity:'Uncommon',icon:'♢',defense:9,upgrade:0,locked:false}],equipped:0,companions:[{name:'Vesper',type:'SHADOW WOLF',level:4,icon:'狼',active:true},{name:'Hollow Wisp',type:'ARCANE COMPANION',level:3,icon:'✧',active:true},{name:'Mossback',type:'ANCIENT GOLEM',level:2,icon:'◉',active:true}],attributes:{Strength:12,Agility:9,Vitality:11,Intelligence:7},claimed:{},bossClaimed:false,last:Date.now(),sound:false,auto:true});
  let state;
  try { const base=fresh(); state={...base,...JSON.parse(localStorage.getItem(KEY)||'{}')}; state.attributes={...base.attributes,...(state.attributes||{})}; state.inventory=Array.isArray(state.inventory)?state.inventory:base.inventory; state.companions=Array.isArray(state.companions)?state.companions:base.companions; state.claimed=state.claimed||{}; state.runLoot=state.runLoot||0; state.bossClaimed=Boolean(state.bossClaimed); state.maxHp=Number(state.maxHp)||base.maxHp; state.hp=clamp(Number(state.hp)||base.hp,0,state.maxHp); state.auto=state.auto!==false; } catch { state=fresh(); }
  const enemyTypes=[{name:'Catacomb Guard',type:'SKELETON',hp:180,xp:82,gold:44,color:'#b9c1bd'},{name:'Gravebound Acolyte',type:'UNDEAD',hp:235,xp:105,gold:57,color:'#9bb9a9'},{name:'Hollow Stalker',type:'DARK CREATURE',hp:275,xp:126,gold:66,color:'#977bd4'}];
  let enemy={...enemyTypes[0],maxHp:180},enemyHp=140,attackClock=0,lastFrame=performance.now(),playerX=.49,targetX=.72,hitFlash=0,shake=0,particles=[],floating=[],cooldowns={strike:0,burst:0,heal:0,ultimate:0},modalLock=false,sceneW=800,sceneH=600,audio;
  const canvas=$('#gameCanvas'),ctx=canvas.getContext('2d');
  function save(){state.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('Save unavailable',e)}}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
  function updateHud(){const xpPct=state.xp/state.xpNext*100,hpPct=state.hp/state.maxHp*100;$('#gold').textContent=fmt(state.gold);$('#aether').textContent=fmt(state.aether);$('#side-level').textContent=state.level;$('.level-orb').textContent=state.level;$('#healthText').textContent=`${fmt(state.hp)} / ${fmt(state.maxHp)}`;$('#playerHealth').style.width=`${hpPct}%`;$('#xpText').textContent=`${fmt(state.xp)} / ${fmt(state.xpNext)} XP`;$('#xpBar').style.width=`${xpPct}%`;$('#waveNum').textContent=String(state.wave).padStart(2,'0');$('#side-wave').textContent=String(state.wave).padStart(2,'0');$('#waveEnemies').textContent=String(Math.max(0,5-state.waveKills));$('#waveBar').style.width=`${Math.min(100,state.waveKills/5*100)}%`;$('#enemyName').textContent=enemy.name;$('#enemyLevel').textContent=`LV. ${String(Math.min(25,4+state.wave)).padStart(2,'0')}`;$('#enemyType').textContent=enemy.type;$('#enemyHealth').style.width=`${clamp(enemyHp/enemy.maxHp*100,0,100)}%`;$('#enemyHpText').textContent=`${fmt(Math.max(0,enemyHp))} / ${fmt(enemy.maxHp)}`;$('#runGold').textContent=`+${fmt(state.runGold)}`;$('#runXp').textContent=`+${fmt(state.runXp)}`;$('#runLoot').textContent=String(state.runLoot);$('#power').textContent=fmt(state.attack*10+state.defense*4+state.level*12);$('#objectiveBar').style.width=`${Math.min(100,(state.wave-1)*10+state.waveKills*2)}%`;$('#objectiveText').textContent=`${Math.min(10,state.wave-1)} / 10`;$('.auto-toggle').classList.toggle('off',!state.auto);$('.auto-toggle b').textContent=state.auto?'ON':'OFF';$('#attackTimer').textContent=`${Math.max(0,2.1-attackClock).toFixed(1)}s`;$('.companion-mini:nth-of-type(1) .companion-state')?.classList.toggle('resting',!state.companions[0]?.active)}
  function addFeed(text){const f=$('#combatFeed'),d=document.createElement('div');d.innerHTML='<i></i> '+text;f.prepend(d);while(f.children.length>3)f.lastElementChild.remove()}
  function gainXp(amount){state.xp+=amount;state.runXp+=amount;while(state.xp>=state.xpNext){state.xp-=state.xpNext;state.level++;state.points+=3;state.maxHp+=38;state.hp=Math.min(state.maxHp,state.hp+90);state.attack+=4;state.xpNext=Math.round(state.xpNext*1.22);toast(`LEVEL UP · LEVEL ${state.level}`);addFeed(`Hunter reached level ${state.level}`)}updateHud()}
  function burstParticles(x,y,color,n=15){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*170;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.65,max:.8,color,size:1+Math.random()*3})}}
  function dropLoot(boss=false){if(state.inventory.length>=40){toast('Inventory full · visit Equipment to sell items');return}const rarity=boss?'Epic':['Common','Common','Uncommon','Rare'][Math.floor(Math.random()*4)],index=Math.floor(Math.random()*5),names=['Ashen Sabatons','Gravetide Ring','Warden’s Grips','Boneglass Charm','Duskfall Circlet'],slots=['Boots','Ring','Gloves','Artifact','Helmet'];state.inventory.push({name:names[index],slot:slots[index],rarity,icon:['♧','◇','♢','✧','⌑'][index],attack:Math.floor(4+Math.random()*12)+(boss?12:0),defense:Math.floor(2+Math.random()*8)+(boss?7:0),upgrade:0,locked:false});state.runLoot++;$('#lootToast').innerHTML='✦ <span>'+rarity+' · '+names[index]+'</span>';$('#lootToast').classList.add('show');setTimeout(()=>$('#lootToast').classList.remove('show'),2400);addFeed(`${rarity} equipment recovered`);save()}
  function spawnEnemy(){if(state.wave>=10&&enemy.name==='THE SKELETON KING'&&enemyHp>0)return;enemy={...enemyTypes[Math.floor(Math.random()*enemyTypes.length)]};enemy.maxHp=Math.round(enemy.hp*(1+Math.max(0,state.wave-1)*.19));enemyHp=enemy.maxHp;targetX=.66+Math.random()*.15;updateHud()}
  function killEnemy(){const boss=enemy.name==='THE SKELETON KING';state.kills++;if(boss){const reward=state.bossClaimed?0:15;state.gold+=450;state.runGold+=450;if(reward){state.aether+=reward;state.bossClaimed=true}gainXp(enemy.xp*4);dropLoot(true);addFeed(reward?'Skeleton King defeated · 15 Aether acquired':'Skeleton King defeated');toast(reward?'GATE CLEARED · +15 AETHER':'GATE CLEARED');$('#skipWave').classList.add('show');$('#bossAlert').classList.remove('show');state.wave=1;state.waveKills=0;enemyHp=0;setTimeout(()=>$('#skipWave').classList.remove('show'),8000);spawnEnemy()}else{state.waveKills++;const gold=enemy.gold+Math.floor(Math.random()*13);state.gold+=gold;state.runGold+=gold;gainXp(enemy.xp);if(Math.random()<.14)dropLoot();if(state.waveKills>=5){state.wave++;state.waveKills=0;addFeed(`Wave ${state.wave} · new threats incoming`);if(state.wave===10){enemy={name:'THE SKELETON KING',type:'GATE GUARDIAN',hp:1850,maxHp:1850,xp:300,gold:250,color:'#d9bd7d'};enemyHp=enemy.hp;$('#bossAlert').classList.add('show');setTimeout(()=>$('#bossAlert').classList.remove('show'),2500)}else spawnEnemy()}else spawnEnemy()}updateHud();save()}
  function playerHit(power=1,label='STRIKE'){if(enemyHp<=0)return;const bonus=state.inventory[state.equipped]?.attack||0,crit=Math.random()<.14,value=Math.round((state.attack+bonus)*power*(crit?1.8:1));enemyHp-=value;hitFlash=.2;shake=crit?7:3;floating.push({x:sceneW*(targetX-.05),y:sceneH*.48,text:`${crit?'✦ ':''}${value}`,life:1,color:crit?'#f4cf77':'#f2eee7'});burstParticles(sceneW*targetX,sceneH*.53,crit?'#f5cb73':'#8de1e6',crit?18:9);if(label!=='STRIKE')addFeed(`${label} · ${value} damage`);if(state.sound)playTone(360,0.07);if(enemyHp<=0)killEnemy();updateHud()}
  function useSkill(name){if(modalLock)return;if(cooldowns[name]>0){toast(`${name.toUpperCase()} · ${Math.ceil(cooldowns[name])}s cooldown`);return}const btn=$(`[data-skill="${name}"]`);if(name==='strike'){playerHit(2.2,'RENDING STRIKE');cooldowns[name]=7}else if(name==='burst'){playerHit(1.35,'UMBRAL NOVA');if(enemyHp>0)playerHit(1.35,'NOVA ECHO');burstParticles(sceneW*targetX,sceneH*.55,'#ac8cf4',35);cooldowns[name]=12}else if(name==='heal'){const healed=Math.min(state.maxHp-state.hp,Math.round(state.maxHp*.38));if(!healed){toast('Health is already full');return}state.hp+=healed;floating.push({x:sceneW*.47,y:sceneH*.52,text:`+${healed} HP`,life:1,color:'#8de7be'});burstParticles(sceneW*.49,sceneH*.67,'#79e5bf',22);cooldowns[name]=18;toast(`SECOND BREATH · +${healed} HP`)}else{playerHit(4.5,'NIGHTFALL · ULTIMATE');burstParticles(sceneW*targetX,sceneH*.5,'#c39aff',48);cooldowns[name]=35}if(btn){btn.classList.add('cooling');btn.dataset.cooldown=String(cooldowns[name])}updateHud();save()}
  function handleOffline(){const elapsed=Math.max(0,Math.min(8*3600,(Date.now()-(Number(state.last)||Date.now()))/1000));if(elapsed<120)return;const kills=Math.floor(elapsed/15),xp=kills*enemyTypes[0].xp,gold=kills*enemyTypes[0].gold;state.gold+=gold;state.runGold+=gold;gainXp(xp);state.kills+=kills;state.last=Date.now();save();setTimeout(()=>openModal(`<div class="eyebrow">RETURNING HUNTER · ${Math.floor(elapsed/60)} MIN AWAY</div><h2>EXPEDITION REPORT</h2><p>Your hunter kept exploring the Forgotten Catacombs while you were away. Offline rewards are capped at 8 hours.</p><div class="modal-stats"><div><small>MONSTERS DEFEATED</small><b>${fmt(kills)}</b></div><div><small>EXPERIENCE EARNED</small><b>+${fmt(xp)} XP</b></div><div><small>GOLD RECOVERED</small><b>+${fmt(gold)}</b></div><div><small>TIME SIMULATED</small><b>${Math.floor(elapsed/60)} min</b></div></div><button class="action-button" id="claimOffline">CLAIM REWARDS</button>`),500)}
  function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.remove('hidden');modalLock=true;$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#claimOffline')?.addEventListener('click',closeModal)}function closeModal(){$('#modalBackdrop').classList.add('hidden');modalLock=false}
  function view(name){const battle=$('#battleView'),content=$('#contentView');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='battle'){battle.classList.remove('hidden');content.classList.add('hidden');return}battle.classList.add('hidden');content.classList.remove('hidden');renderView(name)}
  function header(kicker,title,desc){return `<div class="view-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><button class="back-battle" data-view="battle">◈ &nbsp; RETURN TO BATTLE</button></div>`}
  function renderView(name){const el=$('#contentView'),views={character:renderCharacter,equipment:renderEquipment,skills:renderSkills,companions:renderCompanions,dungeons:renderDungeons,quests:renderQuests,shop:renderShop};(views[name]||renderCharacter)(el);$$('[data-view]',el).forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)))}
  function renderCharacter(el){el.innerHTML=header('HUNTER DOSSIER · RANK F','CHARACTER','A hunter shaped by each descent into the Gate.')+`<div class="content-grid"><div class="info-card"><h3>FIELD ATTRIBUTES <span class="tag">${state.points} POINTS AVAILABLE</span></h3><div class="stat-grid">${Object.entries(state.attributes).map(([k,v])=>`<div class="stat-box"><small>${k.toUpperCase()}</small><b>${v} ${state.points?`<button data-attr="${k}" aria-label="Increase ${k}">+</button>`:''}</b></div>`).join('')}</div></div><div class="info-card"><h3>COMBAT PROFILE</h3><div class="stat-grid"><div class="stat-box"><small>MAX HEALTH</small><b>${fmt(state.maxHp)}</b></div><div class="stat-box"><small>ATTACK</small><b>${fmt(state.attack+(state.inventory[state.equipped]?.attack||0))}</b></div><div class="stat-box"><small>DEFENSE</small><b>${fmt(state.defense+(state.inventory[state.equipped]?.defense||0))}</b></div><div class="stat-box"><small>CRITICAL CHANCE</small><b>14%</b></div></div></div><div class="info-card wide"><h3>HUNTER PROGRESSION</h3><p>Rank F · Novice Hunter. The Hunter examination becomes available at level 10. Your class awakening is still dormant; complete Gate challenges to reveal the power within.</p><div class="meter"><span style="width:${Math.min(100,state.xp/state.xpNext*100)}%"></span></div><p style="margin-top:7px">Level ${state.level} · ${fmt(state.xp)} / ${fmt(state.xpNext)} XP · ${state.kills} monsters defeated</p></div></div>`;$$('[data-attr]',el).forEach(b=>b.onclick=()=>{if(!state.points)return;state.points--;state.attributes[b.dataset.attr]++;if(b.dataset.attr==='Vitality'){state.maxHp+=12;state.hp+=12}if(b.dataset.attr==='Strength')state.attack+=2;save();renderCharacter(el);toast(`${b.dataset.attr} increased`);updateHud()})}
